using System;
using System.IO;
using System.Collections.Generic;
using ParoleRP;
class UsageTests {
 static int count;static void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static ApiReport Report(string op,bool ok=true){return new ApiReport{ok=ok,operation=op,usageEvents=new List<TokenUsage>{new TokenUsage{model="qwen/qwen3.8-27b",inputTokens=400,outputTokens=30,cachedTokens=100},new TokenUsage{model="qwen/qwen3.8-27b",inputTokens=60,outputTokens=10,cachedTokens=0}},routeEvents=new List<RouteEvent>()};}
 static int Main(string[] args){try{string root=Path.Combine(args[0],"usage-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var tracker=new UsageTracker(root);var date=new DateTime(2026,10,31,23,59,0);tracker.Record(Report("correct"),date);var n=tracker.Session;Check(n.Corrections==1&&n.Input==460&&n.Output==40&&n.Cached==100,"context preparation included exactly once");Check(n.CorrectionTokens==400&&n.MeasuredCorrections==1,"per-mode average excludes cached input");tracker.Record(Report("rephrase",false),date);Check(tracker.Session.Failures==1&&tracker.Session.Rephrases==1,"failed request with measured usage retained");tracker.Record(new ApiReport{operation="generate",ok=false},date);Check(tracker.Session.Unreported==1,"missing usage marked unknown");tracker.Reset();Check(tracker.Session.Requests==0&&tracker.Period(1,date).Requests==3,"session reset preserves daily history");tracker.Record(Report("generate"),date.AddMinutes(2));Check(tracker.Period(1,date.AddMinutes(2)).Requests==1&&tracker.Period(2,date).Requests==3,"local midnight and month separated");var reload=new UsageTracker(root);Check(reload.Session.Requests==0&&reload.Period(2,date).Requests==3,"aggregates survive restart but session starts empty");string file=File.ReadAllText(Path.Combine(root,"usage.json"));Check(!file.Contains("qwen")&&!file.Contains("key")&&!file.Contains("texte")&&!file.Contains("character"),"aggregate file contains no prompt, key or profile");File.WriteAllText(Path.Combine(root,"usage.json"),"bad json");var broken=new UsageTracker(root);broken.Record(Report("correct"),date);Check(broken.Warning!=null&&broken.Session.Corrections==1&&File.ReadAllText(Path.Combine(root,"usage.json"))=="bad json","corrupt history preserved and session still works");
 var health=new ConnectionHealth();var now=DateTime.UtcNow;var report=new ApiReport{routeEvents=new List<RouteEvent>{new RouteEvent{connectionId="one",quotaGroup="org",model="qwen",state="quota",retrySeconds=120},new RouteEvent{connectionId="two",quotaGroup="other",model="gpt",state="ready"}}};health.Record(report,now);Check(health.Label("three"," ORG ","qwen",now).StartsWith("Quota"),"quota shared by organization and model");Check(health.Label("one","org","gpt",now)=="À vérifier","creative model quota remains separate");Check(health.Label("one","org","qwen",now.AddSeconds(121))=="À retester","expired quota is not reported as available");health.Record(new ApiReport{routeEvents=new List<RouteEvent>{new RouteEvent{connectionId="two",quotaGroup="other",model="gpt",state="error",code=401}}},now);Check(health.Label("three","other","gpt",now)=="À vérifier"&&health.Label("two","other","gpt",now)=="Erreur 401","invalid key does not mark sibling key invalid");
 var ticket=new UndoTicket{Window=new IntPtr(42),Focus="field-1",Until=now.AddSeconds(30)};Check(ticket.Matches(new IntPtr(42),"field-1",now),"undo same window and field");Check(!ticket.Matches(new IntPtr(43),"field-1",now)&&!ticket.Matches(new IntPtr(42),"field-2",now)&&!ticket.Matches(new IntPtr(42),"field-1",now.AddSeconds(31)),"undo rejects changed window, field and expiry");Check(UndoTicket.ChangesInput(65,false,false)&&UndoTicket.ChangesInput(37,false,false),"typing and caret navigation invalidate undo");Check(!UndoTicket.ChangesInput(90,true,false)&&!UndoTicket.ChangesInput(17,false,false)&&!UndoTicket.ChangesInput(65,false,true),"Ctrl+Z and own injected keys do not invalidate undo");Check(UndoTicket.ChangesInput(90,false,false),"plain Z invalidates undo");
 foreach(string style in new[]{"Toxico","Crapule"}){var c=new Character{DialogueStyle=style};DataFiles.ValidateCharacter(c);Check(c.DialogueStyle==style,"new dialogue style accepted: "+style);}
 Console.WriteLine(count+" usage/health/undo checks passed.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
